import numpy as np,json
from PIL import Image
from rcb_client import Robot
r=Robot(); spec=r.spec(); limits=np.array(spec['qpos']['range']);
def action(q):return np.clip(2*(np.asarray(q)-limits[:,0])/(limits[:,1]-limits[:,0])-1,-1,1)
def save(o,label='latest'):
 for k,v in o.get('images',{}).items():Image.fromarray(v).save('/app/output/'+label+'_'+k+'.png')
 print('obs',o['step'],o['done'],o['reason'],'g',np.round(o['imu']['gravity'],3),'w',np.round(o['imu']['gyro'],3),'q',np.round(o['proprio']['joint_pos'],3),flush=True)
def stand(o,q,n=100,feedback=False):
 for i in range(n):
  t=np.array(q).copy()
  if feedback:
   g=np.array(o['imu']['gravity']);w=np.array(o['imu']['gyro'])
   t[[4,9]]+=1.0*g[0]+.15*w[1]
   t[[1,6]]+=-.5*g[1]+.1*w[0]
  o=r.step('qpos',action(t),images=(i==n-1))
  if o['done']:break
 save(o);return o
if __name__=='__main__':
 o=r.observe(False);q=np.array(o['proprio']['joint_pos']);stand(o,q,100,True)
PY
